const os = require("os");
const path = require("path");
const request = require("supertest");
const vitest = await import("vitest");
const { afterEach, beforeEach, describe, expect, it } = vitest;
const { createApp } = require("../src/app");
const { openDatabase, resetDatabaseForTests } = require("../src/db");
const { seedDemoData } = require("../src/seed");

beforeEach(() => {
  process.env.LIBRARY_DB_PATH = path.join(os.tmpdir(), `library-auth-${Date.now()}-${Math.random()}.sqlite`);
  resetDatabaseForTests();
});

afterEach(() => {
  resetDatabaseForTests();
  delete process.env.LIBRARY_DB_PATH;
});

describe("authentication API", () => {
  it("registers a student and starts a session", async () => {
    const app = createApp();
    const agent = request.agent(app);

    const response = await agent
      .post("/api/auth/register")
      .send({
        name: "New Student",
        memberId: "STU-2002",
        email: "new.student@example.edu",
        password: "password123"
      })
      .expect(200);

    expect(response.body.user).toMatchObject({
      name: "New Student",
      memberId: "STU-2002",
      email: "new.student@example.edu",
      role: "student"
    });
    expect(response.headers["set-cookie"][0]).toContain("HttpOnly");

    const me = await agent.get("/api/auth/me").expect(200);
    expect(me.body.user.email).toBe("new.student@example.edu");
  });

  it("rejects duplicate member IDs and invalid member IDs", async () => {
    const app = createApp();
    await request(app)
      .post("/api/auth/register")
      .send({ name: "One", memberId: "STU-1", email: "one@example.edu", password: "password123" })
      .expect(200);

    await request(app)
      .post("/api/auth/register")
      .send({ name: "Two", memberId: "STU-1", email: "two@example.edu", password: "password123" })
      .expect(409);

    await request(app)
      .post("/api/auth/register")
      .send({ name: "Bad", memberId: "?", email: "bad@example.edu", password: "password123" })
      .expect(400);
  });

  it("logs in seeded student and librarian accounts", async () => {
    const app = createApp();
    seedDemoData();

    const student = await request(app)
      .post("/api/auth/login")
      .send({ email: "student@example.edu", password: "student123" })
      .expect(200);
    const librarian = await request(app)
      .post("/api/auth/login")
      .send({ email: "librarian@example.edu", password: "librarian123" })
      .expect(200);

    expect(student.body.user.role).toBe("student");
    expect(librarian.body.user.role).toBe("librarian");
  });

  it("rejects invalid credentials without revealing account existence", async () => {
    const app = createApp();
    seedDemoData();

    const response = await request(app)
      .post("/api/auth/login")
      .send({ email: "student@example.edu", password: "wrong" })
      .expect(401);

    expect(response.body.message).toBe("Invalid email or password.");
  });

  it("logs out and invalidates the session", async () => {
    const app = createApp();
    seedDemoData();
    const agent = request.agent(app);

    await agent.post("/api/auth/login").send({ email: "student@example.edu", password: "student123" }).expect(200);
    await agent.get("/api/auth/me").expect(200);
    await agent.post("/api/auth/logout").expect(200);
    await agent.get("/api/auth/me").expect(401);
  });

  it("distinguishes unauthenticated and wrong-role requests", async () => {
    const app = createApp();
    seedDemoData();
    const studentAgent = request.agent(app);

    await request(app).get("/api/auth/librarian-only").expect(401);
    await studentAgent.post("/api/auth/login").send({ email: "student@example.edu", password: "student123" }).expect(200);
    await studentAgent.get("/api/auth/student-only").expect(200);
    await studentAgent.get("/api/auth/librarian-only").expect(403);

    const sessions = openDatabase().prepare("SELECT COUNT(*) as count FROM sessions").get();
    expect(sessions.count).toBe(1);
  });
});
